CREATE TABLE customer_profiles (id BIGINT NOT NULL AUTO_INCREMENT, user_id BIGINT NOT NULL, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100), profile_image_url VARCHAR(500), created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_customer_profiles_user(user_id), CONSTRAINT fk_customer_profiles_user FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE addresses (id BIGINT NOT NULL AUTO_INCREMENT, user_id BIGINT NOT NULL, full_name VARCHAR(150) NOT NULL, phone VARCHAR(20) NOT NULL, flat_house_no VARCHAR(150) NOT NULL, street VARCHAR(200) NOT NULL, area_landmark VARCHAR(200), city VARCHAR(100) NOT NULL, state VARCHAR(100) NOT NULL, pincode VARCHAR(10) NOT NULL, address_type VARCHAR(30) NOT NULL, is_default BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY(id), KEY idx_addresses_user(user_id), KEY idx_addresses_user_default(user_id,is_default), KEY idx_addresses_pincode(pincode), CONSTRAINT fk_addresses_user FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
